def sum_nested_parens(paren_strings: List[str]) -> int:
    """ Input to this function is a list of string represented multiple groups for nested parentheses.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> sum_nested_parens(['(()())', '((()))', '()', '((())()())'])
