def max_depth(paren_string: str) -> int:
    """ Input to this function is a string represented a group of nested parentheses.
    Return the highest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> max_depth('(()()) ((())) () ((())()())')
    3
    """
    max_depth, depth = 0, 0
    for char in paren_string:
        if char == '(':
            depth += 1
            if depth > max_depth:
                max_depth = depth
        elif char == ')':
            depth -= 1
    return max_depth


